import { FC } from 'react';

import { Flex, FlexProps, Typography } from 'antd';

import ArrowDown from 'assets/images/icons/change-arrow-down.svg?react';
import ArrowUp from 'assets/images/icons/change-arrow-up.svg?react';

interface IChannelStatChangeProps extends FlexProps {
	arrow?: 'up' | 'down' | 'equal';
	iconSize?: number;
}

export const ChannelStatChange: FC<IChannelStatChangeProps> = ({ children, arrow, iconSize = 18, ...props }) => {
	return (
		<Flex {...props} align="center" gap={4}>
			<Typography.Text type="secondary">{children}</Typography.Text>
			{arrow === 'up' && <ArrowUp width={iconSize} height={iconSize} />}
			{arrow === 'down' && <ArrowDown width={iconSize} height={iconSize} />}
		</Flex>
	);
};
